/* =================================================================================================
FILE:         02_sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly.sql   (Databricks port)
LAYER:        Stored Procedure
PROCEDURE:    sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly

PURPOSE:
  Creates/refreshes physical table sdi_tbl_dashboardPulseTms_bronze_adobeFunnel_weekly.
  Called as part of the weekly refresh.

CHANNEL GROUPS (standard vocabulary):
  'All Channels' | 'Paid Search' | 'Paid Social' | 'Organic Search' |
  'Direct' | 'Programmatic' | 'Other'

PORTING NOTES (BQ -> Databricks), applies to this file only:
  - Adobe/Improvado raw source tables now live under prd_dbi_analytics.improvado.<table>
    (was prj-dbi-prd-1.ds_dbi_improvado_master.<table> in BigQuery) -- per your confirmation.
  - PARSE_DATE('%Y%m%d', date_yyyymmdd) -> to_date(date_yyyymmdd, 'yyyyMMdd')
  - DATE_ADD(x, INTERVAL 6 DAY)         -> date_add(x, 6)
  - SAFE_CAST(x AS FLOAT64)             -> TRY_CAST(x AS DOUBLE)
  - QUALIFY ROW_NUMBER() ... = 1        -> unchanged; Databricks SQL supports QUALIFY natively (DBR 10.4 LTS+)
  - STRING_AGG(DISTINCT x, ', ' ORDER BY x) -> array_join(sort_array(collect_set(x)), ', ')
    ⚠ REVISED after hitting a real Databricks bug: this originally used
    string_agg(DISTINCT x, ', ') WITHIN GROUP (ORDER BY x), which is the more direct syntactic
    equivalent of BQ's STRING_AGG. That works fine with ONE such call in a query, but this
    procedure has TWO (source_tables_used and filenames_used, over different columns) in the
    same GROUP BY. With two different-column DISTINCT string_agg calls in one aggregate,
    Spark's RewriteDistinctAggregates optimizer rule throws a ClassCastException inside
    ListAgg.withNewChildrenInternal (AttributeReference cannot be cast to SortOrder) --
    confirmed against DBR's actual execution, not just a syntax guess. collect_set() +
    sort_array() + array_join() produces the identical result (deduplicated, sorted,
    comma-joined) using older, more mature Spark functions that don't go through that rewrite
    path, so it sidesteps the bug entirely rather than working around it.
  - MAX(IF(cond, val, NULL))            -> unchanged; Databricks SQL supports IF() as a CASE WHEN alias
  - OPTIONS(strict_mode=false)          -> dropped; BQ-scripting-only setting, no Databricks equivalent
  - CREATE TABLE ... PARTITION BY x CLUSTER BY y ... OPTIONS(description=...)
                                         -> CREATE TABLE ... CLUSTER BY (x, y) COMMENT '...'
                                            (Databricks Liquid Clustering supersedes the BQ partition+cluster split)
  - CREATE OR REPLACE PROCEDURE ... BEGIN...END -> needs explicit LANGUAGE SQL clause

CHANGE LOG:
  - 'Social' renamed to 'Paid Social' throughout to align with standard channel_group vocabulary.
================================================================================================= */

CREATE OR REPLACE PROCEDURE
  prdrzranalytics.lab42.sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly()
LANGUAGE SQL
AS
BEGIN

  CREATE OR REPLACE TABLE
    prdrzranalytics.lab42.sdi_tbl_dashboardPulseTms_bronze_adobeFunnel_weekly
  USING DELTA
  CLUSTER BY (week_sun_sat, channel_group)
  COMMENT 'PulseTMS Bronze — Adobe UPV funnel metrics. Wide format, one row per week_sun_sat x channel_group. Clustered by week_sun_sat, channel_group. Refreshed weekly via sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly. Channel groups: All Channels, Paid Search, Paid Social, Organic Search, Direct, Programmatic, Other.'
  AS
  WITH RawUnion AS (

    /* ======= ALL CHANNELS ======= */
    SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6) AS week_sun_sat, 'All Channels' AS channel_group, 'upvPostpaid' AS metric_name, TRY_CAST(visitors AS DOUBLE) AS metric_value, 'sdi_raw_adobe_pp_uvnb_all_uvnb_postpaid_flow_visitors_weekly_tmo' AS source_table, __insert_date AS insert_date, File_Load_datetime AS file_load_datetime, Filename AS filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_uvnb_postpaid_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvHsi',                   TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_uvnb_hsi_flow_visitors_weekly_tmo',                __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_uvnb_hsi_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvByod',                  TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_uvnb_byod_flow_visitors_weekly_tmo',               __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_uvnb_byod_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvFlowTotal',             TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_flow_total_visitors_weekly_tmo',                   __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_flow_total_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvTotalAdobe',            TRY_CAST(visitors AS DOUBLE), 'sdi_raw_pp_pro_uvnb_weekly_tmo',                                            __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_pp_pro_uvnb_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'cartstartPostpaid',        TRY_CAST(visits AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_postpaid_cartstart_visits_weekly_tmo',             __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_postpaid_cartstart_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'cartstartHsi',             TRY_CAST(visits AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_hsi_cartstart_visits_weekly_tmo',                 __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_hsi_cartstart_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'cartstartByod',            TRY_CAST(visits AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_byod_cartstart_visits_weekly_tmo',                __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_byod_cartstart_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersUnassistedPostpaid', TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_postpaid_order_weekly_tmo',                       __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_postpaid_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersUnassistedHsi',      TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_hsi_order_weekly_tmo',                            __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_hsi_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersUnassistedByod',     TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_byod_order_weekly_tmo',                           __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_byod_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersAssistedPostpaid',   TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_postpaid_order_assisted_weekly_tmo',              __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_postpaid_order_assisted_weekly_tmo
