    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersAssistedByod',       TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_all_byod_order_assisted_weekly_tmo',                  __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_byod_order_assisted_weekly_tmo

    /* ======= DIRECT ======= */
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'upvPostpaid',             TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_direct_uvnb_postpaid_flow_visitors_weekly_tmo',        __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_uvnb_postpaid_flow_visitors_weekly_tmo
