    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'cartstartHsi',            TRY_CAST(visits AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_direct_hsi_cartstart_visits_weekly_tmo',               __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_hsi_cartstart_visits_weekly_tmo
