    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'ordersUnassistedPostpaid',TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_direct_postpaid_order_weekly_tmo',                     __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_postpaid_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'ordersUnassistedHsi',     TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_direct_hsi_order_weekly_tmo',                          __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_hsi_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'ordersUnassistedByod',    TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_direct_byod_order_weekly_tmo',                         __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_byod_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'ordersAssistedPostpaid',  TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_direct_postpaid_order_assisted_weekly_tmo',            __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_postpaid_order_assisted_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'ordersAssistedHsi',       TRY_CAST(orders AS DOUBLE),   'sdi_raw_adobe_pp_uvnb_direct_hsi_order_assisted_weekly_tmo',                 __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_hsi_order_assisted_weekly_tmo
